(function() {
  var MarketHelper;

  MarketHelper = require("../lib/market_helper");

  module.exports = function(sequelize, DataTypes) {
    var Transaction;
    Transaction = sequelize.define("Transaction", {
      user_id: {
        type: DataTypes.INTEGER.UNSIGNED,
        allowNull: true
      },
      wallet_id: {
        type: DataTypes.INTEGER.UNSIGNED,
        allowNull: true
      },
      currency: {
        type: DataTypes.INTEGER.UNSIGNED,
        allowNull: false,
        get: function() {
          return MarketHelper.getCurrencyLiteral(this.getDataValue("currency"));
        },
        set: function(currency) {
          return this.setDataValue("currency", MarketHelper.getCurrency(currency));
        }
      },
      account: {
        type: DataTypes.STRING(50)
      },
      fee: {
        type: DataTypes.BIGINT.UNSIGNED,
        defaultValue: 0,
        comment: "FLOAT x 100000000"
      },
      address: {
        type: DataTypes.STRING(34),
        allowNull: false
      },
      amount: {
        type: DataTypes.BIGINT,
        defaultValue: 0,
        allowNull: false,
        comment: "FLOAT x 100000000"
      },
      category: {
        type: DataTypes.INTEGER.UNSIGNED,
        allowNull: false,
        comment: "send, receive",
        get: function() {
          return MarketHelper.getTransactionCategoryLiteral(this.getDataValue("category"));
        },
        set: function(category) {
          return this.setDataValue("category", MarketHelper.getTransactionCategory(category));
        }
      },
      txid: {
        type: DataTypes.STRING(64),
        allowNull: false
      },
      confirmations: {
        type: DataTypes.INTEGER.UNSIGNED,
        defaultValue: 0
      },
      balance_loaded: {
        type: DataTypes.BOOLEAN,
        defaultValue: false
      }
    }, {
      tableName: "transactions",
      getterMethods: {
        network_confirmations: function() {
          return MarketHelper.getMinConfirmations(this.currency);
        }
      },
      classMethods: {
        findById: function(id, callback) {
          return Transaction.find(id).complete(callback);
        },
        findByTxid: function(txid, callback) {
          return Transaction.find({
            where: {
              txid: txid
            }
          }).complete(callback);
        },
        addFromWallet: function(transactionData, currency, wallet, callback) {
          var data, key;
          if (callback == null) {
            callback = function() {};
          }
          data = {
            user_id: (wallet ? wallet.user_id : void 0),
            wallet_id: (wallet ? wallet.id : void 0),
            currency: currency,
            account: transactionData.account,
            fee: transactionData.fee ? MarketHelper.toBigint(transactionData.fee) : void 0,
            address: transactionData.address,
            category: transactionData.category,
            amount: transactionData.amount ? MarketHelper.toBigint(transactionData.amount) : void 0,
            txid: transactionData.txid,
            confirmations: transactionData.confirmations,
            created_at: new Date(transactionData.time * 1000)
          };
          for (key in data) {
            if (data[key] == null) {
              delete data[key];
            }
          }
          return Transaction.findOrCreate({
            txid: data.txid,
            category: MarketHelper.getTransactionCategory(data.category)
          }, data).complete(function(err, transaction, created) {
            if (created) {
              return callback(err, transaction);
            }
            return transaction.updateAttributes(data).complete(callback);
          });
        },
        findPendingByUserAndWallet: function(userId, walletId, callback) {
          var query;
          query = {
            where: {
              user_id: userId,
              wallet_id: walletId,
              category: MarketHelper.getTransactionCategory("receive"),
              balance_loaded: false
            },
            order: [["created_at", "DESC"]]
          };
          return Transaction.findAll(query).complete(callback);
        },
        findProcessedByUserAndWallet: function(userId, walletId, callback) {
          var query;
          query = {
            where: {
              user_id: userId,
              wallet_id: walletId
            },
            order: [["created_at", "DESC"]]
          };
          query.where = sequelize.and(query.where, sequelize.or({
            category: MarketHelper.getTransactionCategory("receive"),
            balance_loaded: true
          }, {
            category: MarketHelper.getTransactionCategory("send")
          }));
          return Transaction.findAll(query).complete(callback);
        },
        findPendingByIds: function(ids, callback) {
          var query;
          if (ids.length === 0) {
            return callback(null, []);
          }
          query = {
            where: {
              txid: ids,
              balance_loaded: false,
              category: MarketHelper.getTransactionCategory("receive")
            },
            order: [["created_at", "DESC"]]
          };
          return Transaction.findAll(query).complete(callback);
        },
        findTotalReceivedByUserAndWallet: function(userId, walletId, callback) {
          var query;
          query = {
            where: {
              user_id: userId,
              wallet_id: walletId,
              balance_loaded: true,
              category: MarketHelper.getTransactionCategory("receive")
            }
          };
          return Transaction.sum("amount", query).complete(function(err, sum) {
            if (sum == null) {
              sum = 0;
            }
            return callback(err, sum);
          });
        },
        isValidFormat: function(category) {
          return !!MarketHelper.getTransactionCategory(category);
        },
        setUserById: function(txid, userId, callback) {
          return Transaction.update({
            user_id: userId
          }, {
            txid: txid
          }).complete(callback);
        },
        setUserAndWalletById: function(txId, userId, walletId, callback) {
          return Transaction.update({
            user_id: userId,
            wallet_id: walletId
          }, {
            txid: txId
          }).complete(callback);
        },
        markAsLoaded: function(id, mysqlTransaction, callback) {
          return Transaction.update({
            balance_loaded: true
          }, {
            id: id
          }, {
            transaction: mysqlTransaction
          }).complete(callback);
        }
      },
      instanceMethods: {
        getFloat: function(attribute) {
          if (this[attribute] == null) {
            return this[attribute];
          }
          return MarketHelper.fromBigint(this[attribute]);
        }
      }
    });
    return Transaction;
  };

}).call(this);

(function() {
  var Emailer, ipFormatter;

  require("date-utils");

  ipFormatter = require("ip");

  Emailer = require("../lib/emailer");

  module.exports = function(sequelize, DataTypes) {
    var AuthStats;
    AuthStats = sequelize.define("AuthStats", {
      user_id: {
        type: DataTypes.INTEGER.UNSIGNED,
        allowNull: false
      },
      ip: {
        type: DataTypes.INTEGER,
        allowNull: true,
        set: function(ip) {
          return this.setDataValue("ip", ipFormatter.toLong(ip));
        },
        get: function() {
          return ipFormatter.fromLong(this.getDataValue("ip"));
        }
      }
    }, {
      tableName: "auth_stats",
      classMethods: {
        findByUser: function(userId, callback) {
          if (callback == null) {
            callback = function() {};
          }
          return AuthStats.findAll({
            where: {
              user_id: userId
            }
          }).complete(callback);
        },
        log: function(data, sendByMail, callback) {
          var stats;
          if (sendByMail == null) {
            sendByMail = true;
          }
          if (callback == null) {
            callback = function() {};
          }
          stats = {
            user_id: data.user.id,
            ip: data.ip
          };
          return AuthStats.create(stats).complete(function(err, authStats) {
            if (sendByMail) {
              AuthStats.sendUserLoginNotice(authStats, data.user.email);
            }
            return callback(err, stats);
          });
        },
        sendUserLoginNotice: function(stats, email, callback) {
          var data, emailer, options;
          if (callback == null) {
            callback = function() {};
          }
          data = {
            ip: stats.ip || "unknown",
            auth_date: stats.created_at.toFormat("MMMM D, YYYY at HH24:MI"),
            email: email
          };
          options = {
            to: {
              email: email
            },
            subject: "Login on Coinnext.com",
            template: "user_login_notice"
          };
          emailer = new Emailer(options, data);
          emailer.send(function(err, result) {
            if (err) {
              return console.error(err);
            }
          });
          return callback();
        }
      }
    });
    return AuthStats;
  };

}).call(this);

(function() {
  var JsonRenderer, Payment, Transaction, TransactionHelper, Wallet, async, paymentsProcessedUserIds, restify, _;

  restify = require("restify");

  async = require("async");

  Wallet = GLOBAL.db.Wallet;

  Transaction = GLOBAL.db.Transaction;

  Payment = GLOBAL.db.Payment;

  JsonRenderer = require("../../lib/json_renderer");

  TransactionHelper = require("../../lib/transaction_helper");

  paymentsProcessedUserIds = [];

  _ = require("underscore");

  module.exports = function(app) {
    app.put("/transaction/:currency/:tx_id", function(req, res, next) {
      var currency, txId;
      txId = req.params.tx_id;
      currency = req.params.currency;
      return GLOBAL.wallets[currency].getTransaction(txId, function(err, walletTransaction) {
        var loadTransactionCallback, subTransactions;
        subTransactions = _.clone(walletTransaction.details);
        delete walletTransaction.details;
        loadTransactionCallback = function(subTransaction, callback) {
          var transactionData;
          transactionData = _.extend(subTransaction, walletTransaction);
          return TransactionHelper.loadTransaction(transactionData, currency, callback);
        };
        return async.mapSeries(subTransactions, loadTransactionCallback, function(err, result) {
          if (err) {
            console.error(err);
          }
          return res.send("" + (new Date()) + " - Added transaction " + txId + " " + currency);
        });
      });
    });
    app.post("/load_latest_transactions/:currency", function(req, res, next) {
      var currency;
      currency = req.params.currency;
      return GLOBAL.wallets[currency].getTransactions("*", 100, 0, function(err, transactions) {
        var loadTransactionCallback;
        if (err) {
          console.error(err);
        }
        loadTransactionCallback = function(transaction, callback) {
          return TransactionHelper.loadTransaction(transaction, currency, callback);
        };
        if (!transactions) {
          return res.send("" + (new Date()) + " - Nothing to process");
        }
        return async.mapSeries(transactions, loadTransactionCallback, function(err, result) {
          if (err) {
            console.error(err);
          }
          return res.send("" + (new Date()) + " - Processed " + result.length + " transactions");
        });
      });
    });
    app.post("/create_payment", function(req, res, next) {
      var data;
      data = req.body;
      return TransactionHelper.createPayment(data, function(err, payment) {
        if (err) {
          return next(new restify.ConflictError(err));
        }
        return res.json(JsonRenderer.payment(payment));
      });
    });
    app.post("/process_pending_payments", function(req, res, next) {
      TransactionHelper.paymentsProcessedUserIds = [];
      return Payment.findToProcess(function(err, payments) {
        return async.mapSeries(payments, TransactionHelper.processPaymentWithFraud, function(err, result) {
          if (err) {
            console.log(err);
          }
          return res.send("" + (new Date()) + " - " + result);
        });
      });
    });
    app.put("/process_payment/:payment_id", function(req, res, next) {
      var paymentId;
      paymentId = req.params.payment_id;
      TransactionHelper.paymentsProcessedUserIds = [];
      return Payment.findNonProcessedById(paymentId, function(err, payment) {
        if (!payment) {
          return next(new restify.ConflictError("Could not find non processed payment " + paymentId));
        }
        return TransactionHelper.processPayment(payment, function(err, result) {
          return Payment.findById(paymentId, function(err, processedPayment) {
            res.send({
              paymentId: paymentId,
              status: processedPayment.status,
              result: result
            });
            if (processedPayment.isProcessed()) {
              return TransactionHelper.pushToUser({
                type: "payment-processed",
                user_id: payment.user_id,
                eventData: JsonRenderer.payment(processedPayment)
              });
            }
          });
        });
      });
    });
    return app.del("/cancel_payment/:payment_id", function(req, res, next) {
      var paymentId;
      paymentId = req.params.payment_id;
      return Payment.findById(paymentId, function(err, payment) {
        if (payment.isProcessed()) {
          return next(new restify.ConflictError("Could not cancel already processed payment " + paymentId + "."));
        }
        return TransactionHelper.cancelPayment(payment, function(err, result) {
          if (err) {
            return next(new restify.ConflictError("Could not cancel already payment " + paymentId + " - " + err));
          }
          return res.send({
            paymentId: paymentId,
            status: "removed"
          });
        });
      });
    });
  };

}).call(this);

